      </div>

      {hovered && (
        <div className="absolute top-2 left-2 z-50 text-[10px] text-white/35 px-2 py-1 rounded-full bg-black/35 border border-white/5 pointer-events-none">
          滚轮切换 · {activeIndex + 1}/{items.length}
        </div>
      )}
    </div>
  );
};

