          scale: 0.98,
        }}
        animate={{
          opacity: 1,
          x: 0,
          y: 0,
          filter: 'blur(0px)',
          scale: 1,
          transition: {
            duration: 0.38,
            ease: [0.22, 1, 0.36, 1],
          },
        }}
        exit={{
          opacity: 0,
          x: direction >= 0 ? -28 : 28,
          filter: 'blur(6px)',
          scale: 0.99,
          transition: { duration: 0.2, ease: [0.4, 0, 1, 1] },
        }}
        className="w-full h-full"
