      >
        <div className="space-y-3 text-[13px] text-white/65 leading-relaxed">
          <p>{openArticle?.body}</p>
          <p className="text-[11px] text-white/35">浏览量 {openArticle?.views} · 可在团队 Wiki 协作编辑（演示）。</p>
